import { db } from "@/db/config";
import { Paste } from "@/db/schema";
import { eq } from "drizzle-orm";
import type { CreatePasteType } from "./paste.schema";
import { EXPIRES_TIME_MS } from "./paste.constant";

export class PasteRepository {
  private readonly dbClient = db;

  async get(code: string) {
    const [paste] = await this.dbClient
      .select()
      .from(Paste)
      .where(eq(Paste.code, code));

    return paste;
  }

  // id is generated by Postgres; content_url is the R2 object key.
  async create(input: CreatePasteType & { title: string; code: string }) {
    const expires_at = new Date(Date.now() + EXPIRES_TIME_MS[input.expiresIn]);
    const [paste] = await this.dbClient
      .insert(Paste)
      .values({
        title: input.title,
        language: input.language,
        code: input.code,
        content_url: `pastes/${input.code}.txt`,
        expires_at,
      })
      .returning();

    return paste;
  }
}
